  9	import com.pousadamaralta.api.controller.RoomController;
 10	import com.pousadamaralta.domain.service.MessageService;
 11	import com.pousadamaralta.domain.service.PricingService;
 12	import com.pousadamaralta.domain.service.ReportService;
 13	import com.pousadamaralta.domain.service.ReservationService;
 14	import com.pousadamaralta.domain.service.RoomService;
 15	import com.pousadamaralta.infrastructure.database.DatabaseInitializer;
 16	import com.pousadamaralta.infrastructure.repository.MessageRepository;
 17	import com.pousadamaralta.infrastructure.repository.ReservationRepository;
 18	import com.pousadamaralta.infrastructure.repository.RoomRepository;
 19	import com.zaxxer.hikari.HikariConfig;
 20	import com.zaxxer.hikari.HikariDataSource;
 21	import io.javalin.Javalin;
 22	import io.javalin.json.JavalinJackson;
 23	
 24	import javax.sql.DataSource;
 25	
 26	public class Main {
 27	
 28	    public static void main(String[] args) {
 29	        String dbUrl = getEnv("DB_URL");
 30	        String dbUser = getEnv("DB_USER");
 31	        String dbPassword = getEnv("DB_PASSWORD");
 32	        int port = Integer.parseInt(getEnv("PORT", "7070"));
 33	
 34	        DataSource dataSource = createDataSource(dbUrl, dbUser, dbPassword);
 35	        DatabaseInitializer.initialize(dataSource);
 36	
 37	        RoomRepository roomRepository = new RoomRepository(dataSource);
 38	        ReservationRepository reservationRepository = new ReservationRepository(dataSource);
 39	        MessageRepository messageRepository = new MessageRepository(dataSource);
 40	
 41	        RoomService roomService = new RoomService(roomRepository);
 42	        PricingService pricingService = new PricingService();
 43	        MessageService messageService = new MessageService(messageRepository);
 44	        ReservationService reservationService = new ReservationService(
 45	            reservationRepository, roomService, pricingService, messageService
 46	        );
 47	        ReportService reportService = new ReportService(reservationRepository, roomService);
 48	
 49	        RoomController roomController = new RoomController(roomService);
 50	        ReservationController reservationController = new ReservationController(
 51	            reservationService, roomService
 52	        );
 53	        MessageController messageController = new MessageController(messageService);
 54	        ReportController reportController = new ReportController(reportService);
 55	
 56	        ObjectMapper objectMapper = new ObjectMapper()
 57	            .registerModule(new JavaTimeModule())
 58	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 59	
 60	        Javalin app = Javalin.create(config -> {
 61	            config.jsonMapper(new JavalinJackson(objectMapper, false));
 62	        });
 63	
 64	        app.get("/rooms", roomController::list);
 65	        app.post("/reservations", reservationController::create);
 66	        app.get("/reservations/{id}", reservationController::get);
 67	        app.post("/reservations/{id}/confirmation", reservationController::confirm);
 68	        app.post("/reservations/{id}/cancellation", reservationController::cancel);
 69	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 70	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 71	        app.get("/reservations/{id}/document", reservationController::getDocument);
 72	        app.get("/messages", messageController::list);
 73	        app.get("/reports/occupancy", reportController::occupancy);
 74	        app.get("/reports/revenue", reportController::revenue);
 75	
 76	        app.start(port);
 77	
 78	        System.out.println("Pousada Maré Alta reservation system running on port " + port);
 79	    }
