 90	    private static String getEnv(String name) {
 91	        String value = System.getenv(name);
 92	        if (value == null) {
 93	            throw new IllegalStateException("Environment variable " + name + " is not set");
 94	        }
 95	        return value;
 96	    }
 97	
 98	    private static String getEnv(String name, String defaultValue) {
 99	        String value = System.getenv(name);
100	        return value != null ? value : defaultValue;
101	    }
