103	package com.pousadamaralta.api.controller;
104	
105	import com.pousadamaralta.api.dto.CreateReservationRequest;
106	import com.pousadamaralta.api.dto.DocumentResponse;
107	import com.pousadamaralta.api.dto.ErrorResponse;
108	import com.pousadamaralta.api.dto.ReservationResponse;
109	import com.pousadamaralta.domain.identification.CnpjIdentification;
110	import com.pousadamaralta.domain.identification.CpfIdentification;
111	import com.pousadamaralta.domain.identification.GuestIdentification;
112	import com.pousadamaralta.domain.identification.PassportIdentification;
113	import com.pousadamaralta.domain.model.RatePlanType;
114	import com.pousadamaralta.domain.model.Reservation;
115	import com.pousadamaralta.domain.model.Room;
116	import com.pousadamaralta.domain.service.ReservationService;
117	import com.pousadamaralta.domain.service.RoomService;
118	import io.javalin.http.Context;
119	import io.javalin.http.HttpStatus;
120	import java.time.LocalDate;
121	import java.time.format.DateTimeParseException;
122	
123	public class ReservationController {
124	    private final ReservationService reservationService;
125	    private final RoomService roomService;
126	
127	    public ReservationController(ReservationService reservationService, RoomService roomService) {
128	        this.reservationService = reservationService;
129	        this.roomService = roomService;
130	    }
131	
132	    public void create(Context ctx) {
133	        CreateReservationRequest request;
134	
135	        try {
136	            request = ctx.bodyAsClass(CreateReservationRequest.class);
137	        } catch (Exception e) {
138	            ctx.status(HttpStatus.BAD_REQUEST)
139	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid request body"));
140	            return;
141	        }
142	
143	        if (!isValidRequest(request)) {
144	            ctx.status(HttpStatus.BAD_REQUEST)
145	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid request parameters"));
146	            return;
147	        }
148	
149	        GuestIdentification identification;
150	        try {
151	            identification = parseIdentification(request);
152	        } catch (InvalidIdentificationException e) {
153	            ctx.status(HttpStatus.BAD_REQUEST)
154	                .json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
155	            return;
156	        }
157	
158	        RatePlanType ratePlanType;
159	        try {
160	            ratePlanType = RatePlanType.valueOf(request.ratePlan());
161	        } catch (Exception e) {
162	            ctx.status(HttpStatus.BAD_REQUEST)
163	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
164	            return;
165	        }
166	
167	        try {
168	            Reservation reservation = reservationService.createReservation(
169	                request.roomNumber(),
170	                request.guestName(),
171	                request.guestEmail(),
172	                identification,
173	                request.checkIn(),
174	                request.checkOut(),
175	                request.guests(),
176	                ratePlanType
177	            );
178	
179	            ctx.status(HttpStatus.CREATED)
180	                .json(ReservationResponse.from(reservation));
181	        } catch (RoomService.RoomNotFoundException e) {
182	            ctx.status(HttpStatus.NOT_FOUND)
183	                .json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
184	        } catch (ReservationService.RoomUnavailableException e) {
185	            ctx.status(HttpStatus.CONFLICT)
186	                .json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
187	        } catch (ReservationService.CapacityExceededException e) {
188	            ctx.status(HttpStatus.UNPROCESSABLE_CONTENT)
189	                .json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
190	        } catch (ReservationService.InvalidRequestException e) {
191	            ctx.status(HttpStatus.BAD_REQUEST)
192	                .json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
193	        }
194	    }
195	
196	    public void get(Context ctx) {
197	        Long id;
198	        try {
199	            id = Long.parseLong(ctx.pathParam("id"));
200	        } catch (NumberFormatException e) {
201	            ctx.status(HttpStatus.BAD_REQUEST)
202	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
203	            return;
204	        }
205	
206	        try {
207	            Reservation reservation = reservationService.getReservation(id);
208	            ctx.json(ReservationResponse.from(reservation));
209	        } catch (ReservationService.ReservationNotFoundException e) {
210	            ctx.status(HttpStatus.NOT_FOUND)
211	                .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
212	        }
213	    }
214	
215	    public void confirm(Context ctx) {
216	        Long id;
217	        try {
218	            id = Long.parseLong(ctx.pathParam("id"));
219	        } catch (NumberFormatException e) {
220	            ctx.status(HttpStatus.BAD_REQUEST)
221	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
222	            return;
223	        }
224	
225	        try {
226	            Reservation reservation = reservationService.confirmReservation(id);
227	            ctx.json(ReservationResponse.from(reservation));
228	        } catch (ReservationService.ReservationNotFoundException e) {
229	            ctx.status(HttpStatus.NOT_FOUND)
230	                .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
231	        } catch (ReservationService.OperationNotAllowedException e) {
232	            ctx.status(HttpStatus.CONFLICT)
233	                .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
234	        }
235	    }
236	
237	    public void cancel(Context ctx) {
238	        Long id;
239	        try {
240	            id = Long.parseLong(ctx.pathParam("id"));
241	        } catch (NumberFormatException e) {
242	            ctx.status(HttpStatus.BAD_REQUEST)
243	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
244	            return;
245	        }
246	
247	        try {
248	            Reservation reservation = reservationService.cancelReservation(id);
249	            ctx.json(ReservationResponse.from(reservation));
250	        } catch (ReservationService.ReservationNotFoundException e) {
251	            ctx.status(HttpStatus.NOT_FOUND)
252	                .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
253	        } catch (ReservationService.OperationNotAllowedException e) {
254	            ctx.status(HttpStatus.CONFLICT)
255	                .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
256	        }
257	    }
258	
259	    public void checkIn(Context ctx) {
260	        Long id;
261	        try {
262	            id = Long.parseLong(ctx.pathParam("id"));
263	        } catch (NumberFormatException e) {
264	            ctx.status(HttpStatus.BAD_REQUEST)
265	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
266	            return;
267	        }
268	
269	        try {
270	            Reservation reservation = reservationService.checkIn(id);
271	            ctx.json(ReservationResponse.from(reservation));
272	        } catch (ReservationService.ReservationNotFoundException e) {
273	            ctx.status(HttpStatus.NOT_FOUND)
274	                .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
275	        } catch (ReservationService.OperationNotAllowedException e) {
276	            ctx.status(HttpStatus.CONFLICT)
277	                .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
278	        }
279	    }
280	
281	    public void checkOut(Context ctx) {
282	        Long id;
283	        try {
284	            id = Long.parseLong(ctx.pathParam("id"));
285	        } catch (NumberFormatException e) {
286	            ctx.status(HttpStatus.BAD_REQUEST)
287	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
288	            return;
289	        }
290	
291	        try {
292	            Reservation reservation = reservationService.checkOut(id);
293	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
294	
295	            String documentText = reservation.getIdentification().generateDocument(
296	                reservation.getId(),
297	                reservation.getGuestName(),
298	                reservation.getRoomNumber(),
299	                room.getType(),
300	                reservation.getCheckIn(),
301	                reservation.getCheckOut(),
302	                reservation.getNights(),
303	                reservation.getSubtotal(),
304	                reservation.getDiscount(),
305	                reservation.getTotal()
306	            );
307	
308	            ctx.json(DocumentResponse.from(reservation, room, documentText));
309	        } catch (ReservationService.ReservationNotFoundException e) {
310	            ctx.status(HttpStatus.NOT_FOUND)
311	                .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
312	        } catch (ReservationService.OperationNotAllowedException e) {
313	            ctx.status(HttpStatus.CONFLICT)
314	                .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
315	        }
316	    }
317	
318	    public void getDocument(Context ctx) {
319	        Long id;
320	        try {
321	            id = Long.parseLong(ctx.pathParam("id"));
322	        } catch (NumberFormatException e) {
323	            ctx.status(HttpStatus.BAD_REQUEST)
324	                .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
325	            return;
326	        }
327	
328	        try {
329	            Reservation reservation = reservationService.getReservation(id);
330	
331	            if (!reservation.isPaid()) {
332	                ctx.status(HttpStatus.CONFLICT)
333	                    .json(new ErrorResponse("OPERATION_NOT_ALLOWED",
334	                        "Document only available for paid reservations"));
335	                return;
336	            }
337	
338	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
339	
340	            String documentText = reservation.getIdentification().generateDocument(
341	                reservation.getId(),
342	                reservation.getGuestName(),
343	                reservation.getRoomNumber(),
344	                room.getType(),
345	                reservation.getCheckIn(),
346	                reservation.getCheckOut(),
347	                reservation.getNights(),
348	                reservation.getSubtotal(),
349	                reservation.getDiscount(),
350	                reservation.getTotal()
351	            );
352	
353	            ctx.json(DocumentResponse.from(reservation, room, documentText));
354	        } catch (ReservationService.ReservationNotFoundException e) {
355	            ctx.status(HttpStatus.NOT_FOUND)
356	                .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
357	        }
358	    }
359	
360	    private boolean isValidRequest(CreateReservationRequest request) {
361	        return request.roomNumber() != null &&
362	               request.guestName() != null &&
363	               request.guestEmail() != null &&
364	               request.checkIn() != null &&
365	               request.checkOut() != null &&
366	               request.guests() != null &&
367	               request.ratePlan() != null;
368	    }
369	
370	    private GuestIdentification parseIdentification(CreateReservationRequest request) {
371	        int identificationCount = 0;
372	
373	        if (request.guestCpf() != null) identificationCount++;
374	        if (request.companyCnpj() != null) identificationCount++;
375	        if (request.guestPassport() != null) identificationCount++;
376	
377	        if (identificationCount != 1) {
378	            throw new InvalidIdentificationException(
379	                "Exactly one identification type must be provided"
380	            );
381	        }
382	
383	        if (request.guestCpf() != null) {
384	            return new CpfIdentification(request.guestCpf());
385	        }
386	
387	        if (request.companyCnpj() != null) {
388	            if (request.companyName() == null) {
389	                throw new InvalidIdentificationException(
390	                    "Company name is required when CNPJ is provided"
391	                );
392	            }
393	            return new CnpjIdentification(request.companyCnpj(), request.companyName());
394	        }
395	
396	        if (request.guestPassport() != null) {
397	            if (request.guestCountry() == null) {
398	                throw new InvalidIdentificationException(
399	                    "Country is required when passport is provided"
400	                );
401	            }
402	            return new PassportIdentification(request.guestPassport(), request.guestCountry());
403	        }
404	
405	        throw new InvalidIdentificationException("No valid identification provided");
406	    }
407	
408	    private static class InvalidIdentificationException extends RuntimeException {
409	        public InvalidIdentificationException(String message) {
410	            super(message);
411	        }
412	    }
413	}

