370	    private GuestIdentification parseIdentification(CreateReservationRequest request) {
371	        int identificationCount = 0;
372	
373	        if (request.guestCpf() != null) identificationCount++;
374	        if (request.companyCnpj() != null) identificationCount++;
375	        if (request.guestPassport() != null) identificationCount++;
376	
377	        if (identificationCount != 1) {
378	            throw new InvalidIdentificationException(
379	                "Exactly one identification type must be provided"
380	            );
381	        }
382	
383	        if (request.guestCpf() != null) {
384	            return new CpfIdentification(request.guestCpf());
385	        }
386	
387	        if (request.companyCnpj() != null) {
388	            if (request.companyName() == null) {
389	                throw new InvalidIdentificationException(
390	                    "Company name is required when CNPJ is provided"
391	                );
392	            }
393	            return new CnpjIdentification(request.companyCnpj(), request.companyName());
394	        }
395	
396	        if (request.guestPassport() != null) {
397	            if (request.guestCountry() == null) {
398	                throw new InvalidIdentificationException(
399	                    "Country is required when passport is provided"
400	                );
401	            }
402	            return new PassportIdentification(request.guestPassport(), request.guestCountry());
403	        }
404	
405	        throw new InvalidIdentificationException("No valid identification provided");
406	    }
407	
408	    private static class InvalidIdentificationException extends RuntimeException {
409	        public InvalidIdentificationException(String message) {
410	            super(message);
411	        }
412	    }
413	}

