138	public class ReportService {
139	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
140	
141	    private final ReservationRepository reservationRepository;
142	    private final RoomService roomService;
143	
144	    public ReportService(ReservationRepository reservationRepository, RoomService roomService) {
145	        this.reservationRepository = reservationRepository;
146	        this.roomService = roomService;
147	    }
148	
149	    public String generateOccupancyReport(LocalDate date) {
150	        List<Reservation> reservations = reservationRepository.findPaidReservationsForNight(date);
151	        List<Room> allRooms = roomService.getAllRooms();
152	
153	        StringBuilder csv = new StringBuilder();
154	        csv.append("room,type,reservation,check_in,check_out\n");
155	
156	        for (Reservation reservation : reservations) {
157	            csv.append(reservation.getRoomNumber()).append(",");
158	
159	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
160	            csv.append(room.getType().name()).append(",");
161	            csv.append(reservation.getId()).append(",");
162	            csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
163	            csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append("\n");
164	        }
165	
166	        int occupiedCount = reservations.size();
167	        int totalCount = allRooms.size();
168	        csv.append("total,").append(occupiedCount).append("/").append(totalCount);
169	
170	        return csv.toString();
171	    }
172	
173	    public String generateRevenueReport(YearMonth month) {
174	        List<Reservation> reservations = reservationRepository.findRevenueReservationsForMonth(month);
175	
176	        StringBuilder csv = new StringBuilder();
177	        csv.append("reservation,room,check_in,check_out,status,amount\n");
178	
179	        BigDecimal totalRevenue = BigDecimal.ZERO;
180	
181	        for (Reservation reservation : reservations) {
182	            BigDecimal revenue = reservation.getAmountPaid();
183	            if (reservation.getRefund() != null) {
184	                revenue = revenue.subtract(reservation.getRefund());
185	            }
186	
187	            csv.append(reservation.getId()).append(",");
188	            csv.append(reservation.getRoomNumber()).append(",");
189	            csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
190	            csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append(",");
191	            csv.append(reservation.getStatus().name()).append(",");
192	            csv.append(formatCsvAmount(revenue)).append("\n");
193	
194	            totalRevenue = totalRevenue.add(revenue);
195	        }
196	
197	        csv.append("total,").append(formatCsvAmount(totalRevenue));
198	
199	        return csv.toString();
200	    }
201	
202	    private String formatCsvAmount(BigDecimal amount) {
203	        return amount.toString();
204	    }
205	}
