 53	package com.pousadamaralta.domain.service;
 54	
 55	import com.pousadamaralta.domain.model.Room;
 56	import com.pousadamaralta.domain.model.RatePlanType;
 57	import com.pousadamaralta.domain.rateplan.RatePlan;
 58	import com.pousadamaralta.domain.rateplan.RatePlanFactory;
 59	import java.math.BigDecimal;
 60	import java.math.RoundingMode;
 61	import java.time.LocalDate;
 62	import java.time.Month;
 63	
 64	public class PricingService {
 65	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 66	
 67	    public BigDecimal calculateNightPrice(Room room, LocalDate night) {
 68	        BigDecimal basePrice = room.getNightlyRate();
 69	
 70	        if (isHighSeason(night)) {
 71	            return basePrice.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
 72	        }
 73	
 74	        return basePrice;
 75	    }
 76	
 77	    public BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
 78	        BigDecimal subtotal = BigDecimal.ZERO;
 79	        LocalDate current = checkIn;
 80	
 81	        while (current.isBefore(checkOut)) {
 82	            BigDecimal nightPrice = calculateNightPrice(room, current);
 83	            subtotal = subtotal.add(nightPrice);
 84	            current = current.plusDays(1);
 85	        }
 86	
 87	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
 88	    }
 89	
 90	    public BigDecimal calculateDiscount(RatePlanType ratePlanType, BigDecimal subtotal) {
 91	        RatePlan plan = RatePlanFactory.get(ratePlanType);
 92	        return plan.calculateDiscount(subtotal);
 93	    }
 94	
 95	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
 96	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
 97	    }
 98	
 99	    public BigDecimal calculateRefund(RatePlanType ratePlanType, BigDecimal amountPaid, BigDecimal total) {
100	        RatePlan plan = RatePlanFactory.get(ratePlanType);
101	        return plan.calculateRefund(amountPaid, total);
102	    }
103	
104	    private boolean isHighSeason(LocalDate date) {
105	        Month month = date.getMonth();
106	        int day = date.getDayOfMonth();
107	
108	        if (month == Month.JULY) {
109	            return true;
110	        }
111	
112	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
113	            return true;
114	        }
115	
116	        if (month == Month.DECEMBER && day >= 15) {
117	            return true;
118	        }
119	
120	        return false;
121	    }
122	
123	    public int calculateNights(LocalDate checkIn, LocalDate checkOut) {
124	        return (int) checkIn.until(checkOut).getDays();
125	    }
126	}
