216	import java.util.List;
217	
218	public class ReservationService {
219	    private final ReservationRepository reservationRepository;
220	    private final RoomService roomService;
221	    private final PricingService pricingService;
222	    private final MessageService messageService;
223	
224	    public ReservationService(
225	            ReservationRepository reservationRepository,
226	            RoomService roomService,
227	            PricingService pricingService,
228	            MessageService messageService
229	    ) {
230	        this.reservationRepository = reservationRepository;
231	        this.roomService = roomService;
232	        this.pricingService = pricingService;
233	        this.messageService = messageService;
234	    }
235	
236	    public Reservation createReservation(
237	            String roomNumber,
238	            String guestName,
239	            String guestEmail,
240	            GuestIdentification identification,
241	            LocalDate checkIn,
242	            LocalDate checkOut,
243	            int guests,
244	            RatePlanType ratePlanType
245	    ) {
246	        Room room = roomService.getRoomByNumber(roomNumber);
247	
248	        if (guests < 1) {
249	            throw new InvalidRequestException("At least one guest is required");
250	        }
251	
252	        if (guests > room.getCapacity()) {
253	            throw new CapacityExceededException(guests, room.getCapacity());
254	        }
255	
256	        if (!checkOut.isAfter(checkIn)) {
257	            throw new InvalidRequestException("Check-out must be after check-in");
258	        }
259	
260	        List<Reservation> conflicting = reservationRepository.findByRoomAndDateRange(
261	            roomNumber, checkIn, checkOut
262	        );
263	
264	        if (!conflicting.isEmpty()) {
265	            throw new RoomUnavailableException(roomNumber);
266	        }
267	
268	        int nights = pricingService.calculateNights(checkIn, checkOut);
269	        BigDecimal subtotal = pricingService.calculateSubtotal(room, checkIn, checkOut);
270	        BigDecimal discount = pricingService.calculateDiscount(ratePlanType, subtotal);
271	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
272	
273	        Reservation reservation = new Reservation(
274	            null,
275	            roomNumber,
276	            guestName,
277	            guestEmail,
278	            identification,
279	            checkIn,
280	            checkOut,
281	            guests,
282	            ratePlanType,
283	            nights,
284	            subtotal,
285	            discount,
286	            total,
287	            ReservationStatus.PENDING,
288	            BigDecimal.ZERO,
289	            null
290	        );
291	
292	        return reservationRepository.save(reservation);
293	    }
294	
295	    public Reservation getReservation(Long id) {
296	        return reservationRepository.findById(id)
297	            .orElseThrow(() -> new ReservationNotFoundException(id));
298	    }
299	
300	    public Reservation confirmReservation(Long id) {
301	        Reservation reservation = getReservation(id);
302	
303	        if (!reservation.canConfirm()) {
304	            throw new OperationNotAllowedException(
305	                "Cannot confirm reservation in status " + reservation.getStatus()
306	            );
307	        }
308	
309	        reservation.confirm();
310	        reservation = reservationRepository.save(reservation);
311	
312	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
313	        messageService.sendConfirmationEmail(reservation, room);
314	
315	        return reservation;
316	    }
317	
318	    public Reservation cancelReservation(Long id) {
319	        Reservation reservation = getReservation(id);
320	
321	        if (!reservation.canCancel()) {
322	            throw new OperationNotAllowedException(
323	                "Cannot cancel reservation in status " + reservation.getStatus()
324	            );
325	        }
326	
327	        BigDecimal refund = pricingService.calculateRefund(
328	            reservation.getRatePlanType(),
329	            reservation.getAmountPaid(),
330	            reservation.getTotal()
331	        );
332	
333	        reservation.cancel(refund);
334	        return reservationRepository.save(reservation);
335	    }
336	
337	    public Reservation checkIn(Long id) {
338	        Reservation reservation = getReservation(id);
339	
340	        if (!reservation.canCheckIn()) {
341	            throw new OperationNotAllowedException(
342	                "Cannot check in reservation in status " + reservation.getStatus()
343	            );
344	        }
345	
346	        reservation.checkIn();
347	        return reservationRepository.save(reservation);
348	    }
349	
350	    public Reservation checkOut(Long id) {
351	        Reservation reservation = getReservation(id);
352	
353	        if (!reservation.canCheckOut()) {
354	            throw new OperationNotAllowedException(
355	                "Cannot check out reservation in status " + reservation.getStatus()
356	            );
357	        }
358	
359	        reservation.checkOut();
360	        return reservationRepository.save(reservation);
361	    }
362	
363	    public static class ReservationNotFoundException extends RuntimeException {
364	        public ReservationNotFoundException(Long id) {
365	            super("Reservation not found: " + id);
366	        }
367	    }
368	
369	    public static class RoomUnavailableException extends RuntimeException {
370	        public RoomUnavailableException(String roomNumber) {
371	            super("Room " + roomNumber + " is not available for the selected dates");
372	        }
373	    }
374	
375	    public static class CapacityExceededException extends RuntimeException {
376	        public CapacityExceededException(int requested, int capacity) {
377	            super("Requested " + requested + " guests but room capacity is " + capacity);
378	        }
379	    }
380	
381	    public static class OperationNotAllowedException extends RuntimeException {
382	        public OperationNotAllowedException(String message) {
383	            super(message);
384	        }
385	    }
386	
387	    public static class InvalidRequestException extends RuntimeException {
388	        public InvalidRequestException(String message) {
389	            super(message);
390	        }
391	    }
392	}
