 12	
 13	            stmt.execute("""
 14	                CREATE TABLE IF NOT EXISTS rooms (
 15	                    number VARCHAR(10) PRIMARY KEY,
 16	                    type VARCHAR(20) NOT NULL
 17	                )
 18	            """);
 19	
 20	            stmt.execute("""
