141	import com.pousadamaralta.domain.identification.CnpjIdentification;
142	import com.pousadamaralta.domain.identification.CpfIdentification;
143	import com.pousadamaralta.domain.identification.GuestIdentification;
144	import com.pousadamaralta.domain.identification.PassportIdentification;
145	import com.pousadamaralta.domain.model.RatePlanType;
146	import com.pousadamaralta.domain.model.Reservation;
147	import com.pousadamaralta.domain.model.ReservationStatus;
148	import javax.sql.DataSource;
149	import java.math.BigDecimal;
150	import java.sql.Connection;
151	import java.sql.Date;
152	import java.sql.PreparedStatement;
153	import java.sql.ResultSet;
154	import java.sql.Statement;
155	import java.time.LocalDate;
156	import java.time.YearMonth;
157	import java.util.ArrayList;
158	import java.util.List;
159	import java.util.Optional;
160	
161	public class ReservationRepository {
162	    private final DataSource dataSource;
163	
164	    public ReservationRepository(DataSource dataSource) {
165	        this.dataSource = dataSource;
166	    }
167	
168	    public Reservation save(Reservation reservation) {
169	        if (reservation.getId() == null) {
170	            return insert(reservation);
171	        } else {
172	            return update(reservation);
173	        }
174	    }
175	
176	    private Reservation insert(Reservation reservation) {
177	        String sql = """
178	            INSERT INTO reservations (
179	                room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
180	                guest_passport, guest_country, check_in, check_out, guests, rate_plan_type,
181	                nights, subtotal, discount, total, status, amount_paid, refund
182	            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
183	        """;
184	
185	        try (Connection conn = dataSource.getConnection();
186	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
187	
188	            setReservationParameters(stmt, reservation);
189	            stmt.executeUpdate();
190	
191	            try (ResultSet rs = stmt.getGeneratedKeys()) {
192	                if (rs.next()) {
193	                    long id = rs.getLong(1);
194	                    return new Reservation(
195	                        id,
196	                        reservation.getRoomNumber(),
197	                        reservation.getGuestName(),
198	                        reservation.getGuestEmail(),
199	                        reservation.getIdentification(),
200	                        reservation.getCheckIn(),
201	                        reservation.getCheckOut(),
202	                        reservation.getGuests(),
203	                        reservation.getRatePlanType(),
204	                        reservation.getNights(),
205	                        reservation.getSubtotal(),
206	                        reservation.getDiscount(),
207	                        reservation.getTotal(),
208	                        reservation.getStatus(),
209	                        reservation.getAmountPaid(),
210	                        reservation.getRefund()
211	                    );
212	                }
213	            }
214	        } catch (Exception e) {
215	            throw new RuntimeException("Failed to insert reservation", e);
216	        }
217	
218	        throw new RuntimeException("Failed to get generated ID");
219	    }
220	
221	    private Reservation update(Reservation reservation) {
222	        String sql = """
223	            UPDATE reservations SET
224	                room_number = ?, guest_name = ?, guest_email = ?, guest_cpf = ?, company_cnpj = ?,
225	                company_name = ?, guest_passport = ?, guest_country = ?, check_in = ?, check_out = ?,
226	                guests = ?, rate_plan_type = ?, nights = ?, subtotal = ?, discount = ?, total = ?,
227	                status = ?, amount_paid = ?, refund = ?
228	            WHERE id = ?
229	        """;
230	
231	        try (Connection conn = dataSource.getConnection();
232	             PreparedStatement stmt = conn.prepareStatement(sql)) {
233	
234	            setReservationParameters(stmt, reservation);
235	            stmt.setLong(20, reservation.getId());
236	            stmt.executeUpdate();
237	
238	            return reservation;
239	        } catch (Exception e) {
240	            throw new RuntimeException("Failed to update reservation", e);
241	        }
242	    }
243	
244	    private void setReservationParameters(PreparedStatement stmt, Reservation reservation) throws Exception {
245	        GuestIdentification id = reservation.getIdentification();
246	
247	        stmt.setString(1, reservation.getRoomNumber());
248	        stmt.setString(2, reservation.getGuestName());
249	        stmt.setString(3, reservation.getGuestEmail());
250	        stmt.setString(4, id.getCpf());
251	        stmt.setString(5, id.getCnpj());
252	        stmt.setString(6, id.getCompanyName());
253	        stmt.setString(7, id.getPassport());
254	        stmt.setString(8, id.getCountry());
255	        stmt.setDate(9, Date.valueOf(reservation.getCheckIn()));
256	        stmt.setDate(10, Date.valueOf(reservation.getCheckOut()));
257	        stmt.setInt(11, reservation.getGuests());
258	        stmt.setString(12, reservation.getRatePlanType().name());
259	        stmt.setInt(13, reservation.getNights());
260	        stmt.setBigDecimal(14, reservation.getSubtotal());
261	        stmt.setBigDecimal(15, reservation.getDiscount());
262	        stmt.setBigDecimal(16, reservation.getTotal());
263	        stmt.setString(17, reservation.getStatus().name());
264	        stmt.setBigDecimal(18, reservation.getAmountPaid());
265	
266	        if (reservation.getRefund() != null) {
267	            stmt.setBigDecimal(19, reservation.getRefund());
268	        } else {
269	            stmt.setNull(19, java.sql.Types.DECIMAL);
270	        }
271	    }
272	
273	    public Optional<Reservation> findById(Long id) {
274	        String sql = "SELECT * FROM reservations WHERE id = ?";
275	
276	        try (Connection conn = dataSource.getConnection();
277	             PreparedStatement stmt = conn.prepareStatement(sql)) {
278	
279	            stmt.setLong(1, id);
280	
281	            try (ResultSet rs = stmt.executeQuery()) {
282	                if (rs.next()) {
283	                    return Optional.of(mapReservation(rs));
284	                }
285	            }
286	        } catch (Exception e) {
287	            throw new RuntimeException("Failed to fetch reservation", e);
288	        }
289	
290	        return Optional.empty();
291	    }
292	
293	    public List<Reservation> findByRoomAndDateRange(String roomNumber, LocalDate start, LocalDate end) {
294	        String sql = """
295	            SELECT * FROM reservations
296	            WHERE room_number = ?
297	              AND check_out > ?
298	              AND check_in < ?
299	              AND status != 'CANCELLED'
300	        """;
301	
302	        List<Reservation> reservations = new ArrayList<>();
303	
304	        try (Connection conn = dataSource.getConnection();
305	             PreparedStatement stmt = conn.prepareStatement(sql)) {
306	
307	            stmt.setString(1, roomNumber);
308	            stmt.setDate(2, Date.valueOf(start));
309	            stmt.setDate(3, Date.valueOf(end));
310	
311	            try (ResultSet rs = stmt.executeQuery()) {
312	                while (rs.next()) {
313	                    reservations.add(mapReservation(rs));
314	                }
315	            }
316	        } catch (Exception e) {
317	            throw new RuntimeException("Failed to fetch reservations", e);
318	        }
319	
320	        return reservations;
321	    }
322	
323	    public List<Reservation> findPaidReservationsForNight(LocalDate night) {
324	        String sql = """
325	            SELECT * FROM reservations
326	            WHERE check_in <= ?
327	              AND check_out > ?
328	              AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
329	            ORDER BY room_number
330	        """;
331	
332	        List<Reservation> reservations = new ArrayList<>();
333	
334	        try (Connection conn = dataSource.getConnection();
335	             PreparedStatement stmt = conn.prepareStatement(sql)) {
336	
337	            stmt.setDate(1, Date.valueOf(night));
338	            stmt.setDate(2, Date.valueOf(night));
339	
340	            try (ResultSet rs = stmt.executeQuery()) {
341	                while (rs.next()) {
342	                    reservations.add(mapReservation(rs));
343	                }
344	            }
345	        } catch (Exception e) {
346	            throw new RuntimeException("Failed to fetch reservations for night", e);
347	        }
348	
349	        return reservations;
350	    }
351	
352	    public List<Reservation> findRevenueReservationsForMonth(YearMonth month) {
353	        LocalDate start = month.atDay(1);
354	        LocalDate end = month.atEndOfMonth().plusDays(1);
355	
356	        String sql = """
357	            SELECT * FROM reservations
358	            WHERE check_in >= ?
359	              AND check_in < ?
360	              AND (amount_paid > 0 OR refund IS NOT NULL)
361	            ORDER BY check_in, id
362	        """;
363	
364	        List<Reservation> reservations = new ArrayList<>();
365	
366	        try (Connection conn = dataSource.getConnection();
367	             PreparedStatement stmt = conn.prepareStatement(sql)) {
368	
369	            stmt.setDate(1, Date.valueOf(start));
370	            stmt.setDate(2, Date.valueOf(end));
371	
372	            try (ResultSet rs = stmt.executeQuery()) {
373	                while (rs.next()) {
374	                    reservations.add(mapReservation(rs));
375	                }
376	            }
377	        } catch (Exception e) {
378	            throw new RuntimeException("Failed to fetch revenue reservations", e);
379	        }
380	
381	        return reservations;
382	    }
383	
384	    private Reservation mapReservation(ResultSet rs) throws Exception {
385	        GuestIdentification identification = mapIdentification(rs);
386	
387	        BigDecimal refund = rs.getBigDecimal("refund");
388	        if (rs.wasNull()) {
389	            refund = null;
390	        }
391	
392	        return new Reservation(
393	            rs.getLong("id"),
394	            rs.getString("room_number"),
395	            rs.getString("guest_name"),
396	            rs.getString("guest_email"),
397	            identification,
398	            rs.getDate("check_in").toLocalDate(),
399	            rs.getDate("check_out").toLocalDate(),
400	            rs.getInt("guests"),
401	            RatePlanType.valueOf(rs.getString("rate_plan_type")),
402	            rs.getInt("nights"),
403	            rs.getBigDecimal("subtotal"),
404	            rs.getBigDecimal("discount"),
405	            rs.getBigDecimal("total"),
406	            ReservationStatus.valueOf(rs.getString("status")),
407	            rs.getBigDecimal("amount_paid"),
408	            refund
409	        );
410	    }
411	
412	    private GuestIdentification mapIdentification(ResultSet rs) throws Exception {
413	        String cpf = rs.getString("guest_cpf");
414	        if (cpf != null) {
415	            return new CpfIdentification(cpf);
416	        }
417	
418	        String cnpj = rs.getString("company_cnpj");
419	        if (cnpj != null) {
420	            String companyName = rs.getString("company_name");
421	            return new CnpjIdentification(cnpj, companyName);
422	        }
423	
424	        String passport = rs.getString("guest_passport");
425	        if (passport != null) {
426	            String country = rs.getString("guest_country");
427	            return new PassportIdentification(passport, country);
428	        }
429	
430	        throw new IllegalStateException("Invalid guest identification data");
431	    }
432	}
