273	    public Optional<Reservation> findById(Long id) {
274	        String sql = "SELECT * FROM reservations WHERE id = ?";
275	
276	        try (Connection conn = dataSource.getConnection();
277	             PreparedStatement stmt = conn.prepareStatement(sql)) {
278	
279	            stmt.setLong(1, id);
280	
281	            try (ResultSet rs = stmt.executeQuery()) {
282	                if (rs.next()) {
283	                    return Optional.of(mapReservation(rs));
284	                }
285	            }
286	        } catch (Exception e) {
287	            throw new RuntimeException("Failed to fetch reservation", e);
288	        }
289	
290	        return Optional.empty();
291	    }
