     5	import com.pousadamaralta.domain.model.RatePlanType;
     6	import com.pousadamaralta.domain.service.PricingService;
     7	import org.junit.jupiter.api.Test;
     8	import java.math.BigDecimal;
     9	import java.time.LocalDate;
    10	
    11	import static org.junit.jupiter.api.Assertions.assertEquals;
    12	
    13	class PricingServiceTest {
    14	
    15	    private final PricingService pricingService = new PricingService();
    16	
    17	    @Test
    18	    void testHighSeasonPricing() {
    19	        Room room = new Room("101", RoomType.STANDARD);
    20	
    21	        LocalDate julyDate = LocalDate.of(2027, 7, 10);
    22	        BigDecimal nightPrice = pricingService.calculateNightPrice(room, julyDate);
    23	
    24	        assertEquals(new BigDecimal("299.88"), nightPrice);
    25	    }
    26	
    27	    @Test
    28	    void testLowSeasonPricing() {
    29	        Room room = new Room("101", RoomType.STANDARD);
    30	
    31	        LocalDate marchDate = LocalDate.of(2027, 3, 10);
    32	        BigDecimal nightPrice = pricingService.calculateNightPrice(room, marchDate);
    33	
    34	        assertEquals(new BigDecimal("249.90"), nightPrice);
    35	    }
    36	
    37	    @Test
    38	    void testSubtotalCalculation() {
    39	        Room room = new Room("101", RoomType.STANDARD);
    40	
    41	        LocalDate checkIn = LocalDate.of(2027, 7, 10);
    42	        LocalDate checkOut = LocalDate.of(2027, 7, 12);
    43	        BigDecimal subtotal = pricingService.calculateSubtotal(room, checkIn, checkOut);
    44	
    45	        assertEquals(new BigDecimal("599.76"), subtotal);
    46	    }
    47	
    48	    @Test
    49	    void testNonRefundableDiscount() {
    50	        BigDecimal subtotal = new BigDecimal("599.76");
    51	        BigDecimal discount = pricingService.calculateDiscount(RatePlanType.NON_REFUNDABLE, subtotal);
    52	
    53	        assertEquals(new BigDecimal("89.96"), discount);
    54	    }
    55	
    56	    @Test
    57	    void testStandardNoDiscount() {
    58	        BigDecimal subtotal = new BigDecimal("599.76");
    59	        BigDecimal discount = pricingService.calculateDiscount(RatePlanType.STANDARD, subtotal);
    60	
    61	        assertEquals(BigDecimal.ZERO, discount);
    62	    }
    63	}
#!/bin/bash

# Script de teste básico da API
BASE_URL="http://localhost:7070"

echo "=== Testando API da Pousada Maré Alta ==="
echo

echo "1. Listando quartos..."
curl -s "$BASE_URL/rooms" | jq '.'
echo

echo "2. Criando reserva com CPF..."
curl -s -X POST "$BASE_URL/reservations" \
  -H "Content-Type: application/json" \
  -d '{
    "roomNumber": "101",
    "guestName": "João Silva",
    "guestEmail": "joao@example.com",
    "guestCpf": "123.456.789-00",
    "checkIn": "2027-07-10",
    "checkOut": "2027-07-12",
    "guests": 2,
    "ratePlan": "STANDARD"
  }' | jq '.'
echo

echo "3. Confirmando reserva..."
curl -s -X POST "$BASE_URL/reservations/1/confirmation" | jq '.'
echo

echo "4. Listando mensagens enviadas..."
curl -s "$BASE_URL/messages" | jq '.'
echo

echo "5. Relatório de ocupação..."
curl -s "$BASE_URL/reports/occupancy?date=2027-07-10"
echo

echo "=== Testes concluídos ==="

